const PRESETS = {
  "dolly in": {
    "id": "camera.dolly-in",
    "version": 1,
    "prompt": "The camera glides forward toward the subject in one continuous movement. Nearby objects slide past faster than the distant background as the subject grows larger. One continuous shot."
  },
  "orbit": {
    "id": "camera.orbit",
    "version": 1,
    "prompt": "The camera circles all the way around the subject at a steady height and distance, revealing front, side, back and front again in a continuous shot. One continuous shot."
  },
  "crane up": {
    "id": "camera.crane-up",
    "version": 1,
    "prompt": "The camera lifts above the subject and gradually points downward. More of the surrounding ground becomes visible as the subject recedes below. One continuous shot."
  },
  "pull back reveal": {
    "id": "camera.pull-back-reveal",
    "version": 1,
    "prompt": "Beginning close to the subject, the camera retreats smoothly into a wide shot. Surrounding scenery progressively enters at the edges and reveals the larger setting. One continuous shot."
  },
  "handheld": {
    "id": "camera.handheld",
    "version": 1,
    "prompt": "Small irregular camera movements drift gently up, down and sideways, like a person holding a camera while standing still. The subject remains clearly visible. One continuous shot."
  },
  "static": {
    "id": "camera.static",
    "version": 1,
    "prompt": "The camera holds exactly the same viewpoint and framing throughout the shot. Motion belongs to the subject and the environment inside the stationary frame. One continuous shot."
  }
};
const move = String(inputs.camera_move ?? "").trim();
const preset = PRESETS[move];
if (!preset) throw new Error(`Unknown camera move "${move}". Pick one of: ${Object.keys(PRESETS).join(", ")}.`);
const direction = String(inputs.direction ?? "").trim();
if (direction.length > 600) throw new Error("Direction must be 600 characters or fewer.");
const seed = Number.isInteger(inputs.seed) ? inputs.seed : 42;
const prompt = [direction, preset.prompt].filter(Boolean).join(" ");
const settings = {
  schemaVersion: 1,
  app: "shot-director",
  preset: { id: preset.id, version: preset.version, name: move, family: "local-wan" },
  direction,
  effectivePrompt: prompt,
  seed,
  backend: "comfy-cloud",
  model: "wan2.2_ti2v_5B_fp16",
  resolution: "1280x704",
  frames: 121,
  fps: 24
};
await output("prompt", prompt);
await output("seed", seed);
await output("run_settings", JSON.stringify(settings, null, 2));

